// Validacion de entrada del canal de correo — Anexo H §H.3
// Verifica que la descripcion exista, no este vacia y tenga al menos 10 caracteres.
// Si la validacion falla, emite es_valido=false para que el nodo IF rutee al reenvio.
// Limite maximo: 5000 caracteres (contrato IncidenteCreate del backend).

const items = $input.all();
const result = [];

for (const item of items) {
  const descripcion = item.json.body || item.json.descripcion || item.json.text || '';
  const descripcionTrim = String(descripcion).trim();

  const esValida = descripcionTrim.length >= 10 && descripcionTrim.length <= 5000;

  result.push({
    json: {
      ...item.json,
      descripcion: descripcionTrim,
      es_valido: esValida,
      canal_raw: 'correo'
    }
  });
}

return result;

// Validacion de la respuesta de clasificacion del AI Agent — Anexo H §H.3
// 5 pasos en orden:
//   1. Parseo JSON valido
//   2. Presencia de campos 'categoría' y 'confianza'
//   3. Categoria en el set exacto case-sensitive: {Sistemas, Operaciones, Soporte Técnico}
//   4. Confianza numerica en [0.0, 1.0]
//   Ante cualquier fallo: confianza = 0.0 + requiere_revision_humana = true

const CATEGORIAS_VALIDAS = new Set(['Sistemas', 'Operaciones', 'Soporte Técnico']);
const items = $input.all();
const result = [];

for (const item of items) {
  // Paso 1: Parseo JSON valido
  let parsed = null;
  try {
    const raw = item.json.output || item.json.text || JSON.stringify(item.json);
    parsed = JSON.parse(raw);
  } catch (e) {
    // Fallo paso 1: JSON malformado
    result.push({
      json: {
        ...item.json,
        confianza: 0.0,
        requiere_revision_humana: true,
        error_validacion: 'json_malformado'
      }
    });
    continue;
  }

  // Paso 2: Presencia de campos requeridos
  if (!('categoría' in parsed) || !('confianza' in parsed)) {
    result.push({
      json: {
        ...item.json,
        confianza: 0.0,
        requiere_revision_humana: true,
        error_validacion: 'campos_faltantes'
      }
    });
    continue;
  }

  const categoria = parsed['categoría'];
  const confianza = parsed['confianza'];

  // Paso 3: Categoria exacta case-sensitive
  if (!CATEGORIAS_VALIDAS.has(categoria)) {
    result.push({
      json: {
        ...item.json,
        confianza: 0.0,
        requiere_revision_humana: true,
        error_validacion: 'categoria_invalida'
      }
    });
    continue;
  }

  // Paso 4: Confianza numerica en [0.0, 1.0]
  if (typeof confianza !== 'number' || isNaN(confianza) || confianza < 0.0 || confianza > 1.0) {
    result.push({
      json: {
        ...item.json,
        confianza: 0.0,
        requiere_revision_humana: true,
        error_validacion: 'confianza_fuera_de_rango'
      }
    });
    continue;
  }

  // Respuesta valida: conservar categoria y confianza originales
  const descripcion = parsed['descripcion'] || item.json.descripcion || '';
  result.push({
    json: {
      ...item.json,
      categoría: categoria,
      confianza: confianza,
      descripcion: String(descripcion).trim(),
      prioridad: item.json.prioridad || 'media',
      canal_raw: 'telefonia',
      requiere_revision_humana: false
    }
  });
}

return result;

// Normalizacion de entrada a estructura unificada — tesis §5.3
// Homogeniza la entrada de cualquiera de los tres canales:
//   correo, web, telefonia
// Produce exactamente: { id, timestamp, canal_origen, descripcion }
// canal_origen ∈ { correo, web, telefonia }
//
// Nota de privacidad (C-04 §Decision 2):
//   La descripcion se transmite en texto claro al backend.
//   La pseudonimizacion ocurre en el backend (IncidenteService.create_and_classify).
//   El transporte usa HTTPS.

const { v4: uuidv4 } = require('uuid');
const items = $input.all();
const result = [];

const CANALES_VALIDOS = new Set(['correo', 'web', 'telefonia']);

for (const item of items) {
  // Determinar canal segun lo marcado por el nodo previo
  const canalRaw = item.json.canal_raw || 'correo';
  const canalOrigen = CANALES_VALIDOS.has(canalRaw) ? canalRaw : null;

  if (!canalOrigen) {
    // Canal invalido: derivar a revision humana
    result.push({
      json: {
        ...item.json,
        canal_origen: canalRaw,
        es_valido: false,
        error_normalizacion: 'canal_invalido'
      }
    });
    continue;
  }

  // Extraer descripcion segun canal
  let descripcion = '';
  if (canalOrigen === 'correo') {
    descripcion = item.json.descripcion || item.json.body || item.json.text || '';
  } else if (canalOrigen === 'telefonia') {
    descripcion = item.json.descripcion || item.json.output || item.json.text || '';
  } else if (canalOrigen === 'web') {
    descripcion = item.json.descripcion || item.json.message || item.json.body || '';
  }

  result.push({
    json: {
      id: item.json.id || $execution.id + '-' + Date.now(),
      timestamp: new Date().toISOString(),  // ISO-8601 con milisegundos
      canal_origen: canalOrigen,
      descripcion: String(descripcion).trim(),
      prioridad: item.json.prioridad || 'media',
      es_valido: item.json.es_valido !== undefined ? item.json.es_valido : true
    }
  });
}

return result;

// Marca el canal de origen como web antes de la normalizacion
const item = .item;
return [
  {
    json: {
      ...item.json,
      canal_raw: 'web'
    }
  }
];

// Registro de auditoria - C-05 (fix: todas las ramas, tolerante a rechazo)
// Contrato del evento: { incidente_id, canal_origen, timestamp, categoria, confianza, resultado, retencion_dias }
// EXCLUSION DE PII: la descripcion cruda NO se incluye; solo metadatos y referencias.
// Retencion: 30 dias - declarada aqui; el destino persistente (Docker logging con rotacion)
// se configura en docker-compose.yml segun la guia operativa.
//
// Ramas que llegan a este nodo:
//   - Rama exitosa: item tiene id, categoria, confianza del response HTTP (resultado: 'creado')
//   - Rama de rechazo (datos incompletos): item tiene canal_origen pero NO id/categoria/confianza
//     En ese caso resultado proviene del campo resultado emitido por el validador o se infiere.
const item = $input.item.json;

// Determinar el resultado segun la rama:
// Si el item no tiene id (no paso por HTTP POST), es un rechazo por datos incompletos.
const resultado = item.resultado
  || (item.id ? 'creado' : 'rechazado_datos_incompletos');

const evento = {
  incidente_id: item.id || null,
  canal_origen: item.canal_origen || item.canal_raw || null,
  timestamp: new Date().toISOString(),
  categoria: item.categoria || null,
  confianza: item.confianza ?? null,
  resultado: resultado,
  retencion_dias: 30
};
console.log('[AUDITORIA]', JSON.stringify(evento));
return [{ json: evento }];
